import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{r as t}from"./ThemeToggle-2sZo9z4q.js";import{C as n,M as r,N as i,O as a,P as o,b as s,j as c,k as l,l as u,n as d,o as f,p,t as m,w as h}from"./shared-JA1PGxXr.js";import{t as g}from"./earth-CRIEJXdG.js";import{t as _}from"./CodeEditor-DqHMt3P8.js";var v=t(`Send`,[[`path`,{d:`M14.536 21.686a.5.5 0 0 0 .937-.024l6.5-19a.496.496 0 0 0-.635-.635l-19 6.5a.5.5 0 0 0-.024.937l7.93 3.18a2 2 0 0 1 1.112 1.11z`,key:`1ffxy3`}],[`path`,{d:`m21.854 2.147-10.94 10.939`,key:`12cjpa`}]]),y=e();function b({module:e}){return(0,y.jsxs)(i,{children:[(0,y.jsx)(r,{chip:e??`Глава 3 · Блок 10 · HTTP к Planner`,title:`Первый запрос в Postman`,intro:`Соберём GET в Postman, отправим его учебному серверу Echo и проверим по ответу, какие query-пары дошли. Echo не обращается к задачам Planner.`,tags:[{icon:(0,y.jsx)(v,{size:14}),label:`отправляем GET`},{icon:(0,y.jsx)(g,{size:14}),label:`проверяем ответ Echo`}]}),(0,y.jsxs)(o,{number:`00`,title:`От схемы запроса к настоящему обмену`,children:[(0,y.jsxs)(a,{children:[`Перед стартом разберём новый пример: в `,(0,y.jsx)(`code`,{children:`GET /books?limit=3`}),` method — `,(0,y.jsx)(`code`,{children:`GET`}),`, path — `,(0,y.jsx)(`code`,{children:`/books`}),`, query — `,(0,y.jsx)(`code`,{children:`limit=3`}),`; request body здесь не задан. До отправки нельзя знать status и body ответа.`]}),(0,y.jsx)(`p`,{children:`Теперь добавится реальный обмен по сети. Postman — HTTP-клиент: в нём мы собираем и отправляем запрос. Echo — отдельный учебный сервер, который получает запрос и возвращает ответ с информацией о нём. Схема проста: Postman отправляет request → Echo формирует response → Postman показывает его нам. Planner в этой цепочке не участвует.`}),(0,y.jsxs)(`p`,{children:[`Поэтому ответ Echo подтверждает только то, что получил Echo. Даже если query называется `,(0,y.jsx)(`code`,{children:`is_done`}),` или `,(0,y.jsx)(`code`,{children:`limit`}),`, Echo не фильтрует задачи и не ограничивает список. Позже похожие параметры можно будет отправить собственному API Planner, но сегодня мы проверяем саму передачу запроса.`]}),(0,y.jsx)(m,{caption:`Два направления одного HTTP-обмена`,children:(0,y.jsxs)(f,{label:`Request и response`,children:[(0,y.jsx)(u,{title:`Postman`,shape:`process`,children:(0,y.jsx)(`p`,{children:`Собирает и отправляет request`})}),(0,y.jsx)(d,{label:`HTTP request`}),(0,y.jsx)(u,{title:`Echo`,shape:`process`,children:(0,y.jsx)(`p`,{children:`Получает запрос и готовит response`})}),(0,y.jsx)(d,{label:`HTTP response`}),(0,y.jsx)(u,{title:`Postman`,shape:`process`,children:(0,y.jsx)(`p`,{children:`Показывает status и body`})})]})}),(0,y.jsx)(p,{prompt:`Соединим участника с его ролью.`,leftTitle:`Участник`,rightTitle:`Роль`,pairs:[{left:`Postman`,right:`Собирает и отправляет request`},{left:`Echo`,right:`Получает request и возвращает response`},{left:`Мы`,right:`Сверяем ответ с ожиданием`}],explanation:`Нажатие Send начинает сетевой обмен. До него мы меняем только черновик запроса.`})]}),(0,y.jsxs)(o,{number:`01`,title:`Подготовим адрес Echo`,children:[(0,y.jsx)(a,{children:`В Postman сначала выберем сервер, которому отправим запрос. Environment хранит значения для адреса, а не запускает сервер.`}),(0,y.jsxs)(`p`,{children:[`Создадим или найдём environment `,(0,y.jsx)(`code`,{children:`Echo`}),` и зададим переменную `,(0,y.jsx)(`code`,{children:`base_url`}),` со значением `,(0,y.jsx)(`code`,{children:`https://postman-echo.com`}),`. Затем выберем Echo активным. В запросе укажем `,(0,y.jsx)(`code`,{children:`{{base_url}}/get`}),`: Postman подставит значение переменной, и полный адрес станет `,(0,y.jsx)(`code`,{children:`https://postman-echo.com/get`}),`.`]}),(0,y.jsxs)(`p`,{children:[`Проверьте именно раскрытый URL. Если выбрано другое окружение, переменная пуста или в `,(0,y.jsx)(`code`,{children:`base_url`}),` уже добавлен `,(0,y.jsx)(`code`,{children:`/get`}),`, запрос уйдёт не туда или получит неверный адрес. Имя Echo само по себе ничего не гарантирует — важны активное окружение и его значение. Если подходящее окружение уже настроено, используйте его, не создавая дубликат.`]}),(0,y.jsx)(_,{caption:`Как Postman подставляет base_url`,code:`Echo.base_url = https://postman-echo.com
Request URL = {{base_url}}/get
Итоговый URL = https://postman-echo.com/get`}),(0,y.jsxs)(`p`,{children:[`В адресе схема `,(0,y.jsx)(`code`,{children:`https`}),` задаёт защищённый способ обмена, host `,(0,y.jsx)(`code`,{children:`postman-echo.com`}),` указывает сервер, а path `,(0,y.jsx)(`code`,{children:`/get`}),` выбирает его endpoint. Endpoint — доступная операция сервера; это не локальный файл и не имя функции Python. Для сравнения, в `,(0,y.jsx)(`code`,{children:`https://example.org/catalog`}),` сервер задаёт host, а `,(0,y.jsx)(`code`,{children:`/catalog`}),` — path.`]}),(0,y.jsx)(s,{question:`Что нужно проверить, если в URL остался текст {{base_url}}?`,options:[`Активное окружение и значение переменной`,`Тело ответа Planner`,`Настройки локального Python`],correctIndex:0,explanation:`Postman подставляет переменную из выбранного environment. Пока она не разрешилась, адрес не готов к отправке.`})]}),(0,y.jsxs)(o,{number:`02`,title:`Соберём и отправим первый GET`,children:[(0,y.jsx)(a,{children:`До Send мы редактируем request; после Send читаем отдельный response. Поля с одинаковыми названиями могут относиться к разным сообщениям.`}),(0,y.jsxs)(`p`,{children:[`Выберите method `,(0,y.jsx)(`code`,{children:`GET`}),` и URL `,(0,y.jsx)(`code`,{children:`{{base_url}}/get`}),`. Во вкладке Params пока ничего не добавляйте. Вкладки Headers и Body относятся к исходящему request; в этом GET body оставляем пустым. После отправки Postman покажет ответ отдельно: status, response headers и response body. Пустое тело запроса не мешает серверу вернуть непустое тело ответа.`]}),(0,y.jsxs)(`p`,{children:[`Сначала предскажите, что будет в `,(0,y.jsx)(`code`,{children:`args`}),`, если query отсутствует, затем нажмите Send. При доступном Echo обычно приходит status `,(0,y.jsx)(`code`,{children:`200`}),`, а `,(0,y.jsx)(`code`,{children:`args`}),` пуст. Прочитайте фактический status и body, не подменяйте наблюдение ожиданием: успешная отправка определяется ответом, который вы действительно получили.`]}),(0,y.jsx)(h,{title:`От черновика к проверенному ответу`,label:`ПОСЛЕДОВАТЕЛЬНОСТЬ`,prompt:`Расставим действия в порядке выполнения.`,pieces:[{id:`env`,code:`Выбираем Echo и проверяем base_url`},{id:`request`,code:`Настраиваем GET и Params`},{id:`send`,code:`Нажимаем Send`},{id:`response`,code:`Читаем status и body`},{id:`check`,code:`Сверяем результат с прогнозом`}],correctOrder:[`env`,`request`,`send`,`response`,`check`],explanation:`Адрес и запрос нужно подготовить до отправки; ответ появляется только после сетевого обмена.`,incorrectExplanation:`Сначала проверьте цель и запрос. До Send сервер не получил ваш черновик.`}),(0,y.jsxs)(`p`,{children:[`Если видите HTTP `,(0,y.jsx)(`code`,{children:`404`}),`, сервер ответил, но сообщил, что выбранный ресурс не найден. Если Postman сообщает о DNS или connection error, HTTP-ответ мог не прийти вообще. В таком случае status неизвестен: проверьте активное окружение, раскрытый URL и соединение. Не называйте сетевой сбой ответом 404.`]})]}),(0,y.jsxs)(o,{number:`03`,title:`Добавим query и прочитаем args`,children:[(0,y.jsxs)(a,{children:[`Query — пары имени и значения в URL. Postman строит их во вкладке Params: после первой пары ставится `,(0,y.jsx)(`code`,{children:`?`}),`, следующие отделяются `,(0,y.jsx)(`code`,{children:`&`}),`.`]}),(0,y.jsxs)(`p`,{children:[`Для отдельного примера представьте `,(0,y.jsx)(`code`,{children:`size=4&color=red`}),`. До отправки предскажите две записи в ответе Echo. В URL значения query передаются как текст, поэтому Echo отразит `,(0,y.jsx)(`code`,{children:`"4"`}),`, а не число `,(0,y.jsx)(`code`,{children:`4`}),`. Само имя `,(0,y.jsx)(`code`,{children:`size`}),` не задаёт тип и не объясняет серверу, как использовать значение.`]}),(0,y.jsx)(_,{caption:`Echo отражает query в args`,code:`GET https://postman-echo.com/get?size=4&color=red

response body:
{
  "args": {
    "size": "4",
    "color": "red"
  }
}`}),(0,y.jsxs)(`p`,{children:[`Теперь в Params добавьте две строки: `,(0,y.jsx)(`code`,{children:`is_done`}),` = `,(0,y.jsx)(`code`,{children:`false`}),` и `,(0,y.jsx)(`code`,{children:`limit`}),` = `,(0,y.jsx)(`code`,{children:`2`}),`. До Send проверьте, что обе строки включены, и предскажите значения в `,(0,y.jsx)(`code`,{children:`args`}),`. После отправки найдите их именно в response body. Ожидаются строки `,(0,y.jsx)(`code`,{children:`"false"`}),` и `,(0,y.jsx)(`code`,{children:`"2"`}),`: Echo отражает текст запроса, а не преобразует его в boolean и integer.`]}),(0,y.jsxs)(`p`,{children:[`Status `,(0,y.jsx)(`code`,{children:`200`}),` без нужного `,(0,y.jsx)(`code`,{children:`args.limit`}),` не подтверждает цель упражнения. Сверьте итоговый URL, таблицу Params и ответ. Если обе пары на месте, вы доказали, что они дошли до Echo; это всё ещё ничего не говорит о списке задач Planner.`]}),(0,y.jsx)(s,{question:`Echo вернул args: { is_done: "false", limit: "2" }. Какой вывод точен?`,options:[`Echo получил и отразил две текстовые query-пары`,`Planner отобрал две незавершённые задачи`,`Echo преобразовал значения в bool и int`],correctIndex:0,explanation:`Ответ подтверждает передачу строк Echo. Фильтрация и преобразование типов относятся к логике другого сервера.`})]}),(0,y.jsxs)(o,{number:`04`,title:`Проверим ошибочный маршрут`,children:[(0,y.jsx)(a,{children:`Проверка состоит из отдельных вопросов: пришёл ли HTTP-ответ, какой у него status и содержит ли body ожидаемые query.`}),(0,y.jsxs)(`p`,{children:[`При ошибке соединения HTTP-status может отсутствовать. При `,(0,y.jsx)(`code`,{children:`404`}),` response есть, но результат неуспешен. При `,(0,y.jsx)(`code`,{children:`200`}),` сервер ответил успешно, однако нужные параметры всё равно надо найти в `,(0,y.jsx)(`code`,{children:`args`}),`. Эти наблюдения нельзя заменять одним зелёным индикатором.`]}),(0,y.jsx)(n,{code:`GET https://postman-echo.invalid/get`,question:`Postman не может разрешить host. Что можно заключить?`,options:[`Echo вернул HTTP 404`,`HTTP response мог не прийти, поэтому status пока неизвестен`,`Planner отклонил query`],correctIndex:1,explanation:`Ошибка разрешения имени возникает до чтения HTTP-ответа. В этом запросе Planner не участвовал.`,fix:`Проверьте активное окружение, значение base_url и итоговый адрес перед повторной отправкой.`}),(0,y.jsx)(`p`,{children:`Если ответ получен, но одна пара отсутствует, вернитесь к Params и проверьте включённость строки и итоговый URL. Если ответа нет, сначала проверьте адрес и соединение. Так причина ошибки ведёт к конкретному месту проверки, а не к случайному изменению запроса.`})]}),(0,y.jsxs)(o,{number:`05`,title:`Перенесём способ проверки и сохраним GET`,children:[(0,y.jsx)(a,{children:`Изменим одно значение, заранее предскажем ответ и проверим его. Такой перенос показывает, что мы понимаем связь между Params и args.`}),(0,y.jsxs)(`p`,{children:[`В том же GET замените только `,(0,y.jsx)(`code`,{children:`limit=2`}),` на `,(0,y.jsx)(`code`,{children:`limit=5`}),`. Не отправляя запрос, скажите, что должно измениться в Echo. Затем нажмите Send и проверьте: `,(0,y.jsx)(`code`,{children:`args.is_done`}),` остаётся строкой `,(0,y.jsx)(`code`,{children:`"false"`}),`, а `,(0,y.jsx)(`code`,{children:`args.limit`}),` становится строкой `,(0,y.jsx)(`code`,{children:`"5"`}),`. Верните `,(0,y.jsx)(`code`,{children:`limit=2`}),`, отправьте ещё раз и убедитесь, что исходный результат восстановился.`]}),(0,y.jsxs)(`p`,{children:[`Если ответ всё ещё показывает `,(0,y.jsx)(`code`,{children:`"2"`}),`, проверьте, изменили ли Params и отправили ли текущую версию запроса. Один только отредактированный черновик не меняет уже полученный response. Когда workspace доступен, сохраните рабочий GET в collection `,(0,y.jsx)(`code`,{children:`Planner HTTP Lab`}),` и проверьте повторное открытие. Подробное сохранение, экспорт и импорт относятся к занятию 46.1.`]}),(0,y.jsx)(l,{variant:`connected`,items:[{title:`Подготовить цель`,description:`Выбрать Echo, проверить base_url и итоговый URL.`},{title:`Отправить и сверить`,description:`Добавить две query-пары и найти их строками в args.`},{title:`Проверить перенос`,description:`Предсказать limit=5, отправить, затем вернуть limit=2.`}]}),(0,y.jsx)(`p`,{children:`Результат занятия — отправленный GET к Echo и проверенные значения ответа. Мы не отправляли JSON-body или POST, не запускали FastAPI и не меняли файлы или задачи Planner. Echo environment и, если удалось сохранить, GET можно использовать как исходную точку следующего занятия.`}),(0,y.jsx)(c,{text:`Отправьте GET к Echo, проверьте обе query-пары и самостоятельно перенесите проверку на limit=5.`})]})]})}export{b as Lesson46};